async (page) => {
  // Open terminal if not open
  const toggleBtn = page.locator('.terminal-toggle');
  await toggleBtn.click();
  await page.waitForSelector('.terminal-panel.is-open');

  const commandsToTest = [
    'help',
    'help ls',
    'pwd',
    'ls',
    'ls -la',
    'tree',
    'cd experience',
    'pwd',
    'cd ~',
    'pwd',
    'cat about/about.txt',
    'grep victor',
    'man ls',
    'theme dracula',
    'theme claude',
    'lang en',
    'lang es',
    'sound off',
    'sound on',
    'sudo hire',
    'matrix',
    'exit'
  ];

  const results = {};
  const input = page.locator('#terminal-input');
  const log = page.locator('.terminal-log');

  for (const cmd of commandsToTest) {
    // Clear log or record line count before
    const beforeCount = await log.locator('.terminal-line').count();
    await input.fill(cmd);
    await input.press('Enter');
    // wait a bit for execution
    await page.waitForTimeout(100);
    const lines = await log.locator('.terminal-line').allTextContents();
    results[cmd] = lines.slice(beforeCount);
  }

  return results;
}

