    'cat about/about.txt',
    'grep victor',
    'man ls',
    'theme dracula',
    'theme claude',
    'lang en',
    'lang es',
    'sound off',
    'sound on',
    'sudo hire',
    'matrix',
    'exit'
  ];

  const results = {};
  const input = page.locator('#terminal-input');
  const log = page.locator('.terminal-log');

  for (const cmd of commands) {
    const linesBefore = await log.locator('.terminal-line').count();
    await input.fill(cmd);
    await input.press('Enter');
    // Wait briefly for output rendering / animations
    await page.waitForTimeout(150);
    const linesAfter = await log.locator('.terminal-line').allTextContents();
    results[cmd] = linesAfter.slice(linesBefore);
  }

  return results;
}

