async (page) => {
  const input = await page.$('#terminal-input');
  const log = await page.$('.terminal-log');

  const cmds = [
    'help', 'help ls', 'pwd', 'ls', 'ls -la', 'tree', 
    'cd ~', 'pwd', 'cat about/about.txt', 'grep victor', 
    'man ls', 'theme claude', 'lang en', 'sound off', 
    'sound on', 'matrix', 'exit'
  ];

  const results = [];
  for (const cmd of cmds) {
    const beforeCount = log.querySelectorAll('.terminal-line').length;
    await page.evaluate(({ el, command }) => {
      el.value = command;
      el.dispatchEvent(new Event('input', { bubbles: true }));
      const form = el.closest('form');
      form.dispatchEvent(new Event('submit', { cancelable: true, bubbles: true }));
    }, { el: input, command: cmd });

    await page.waitForTimeout(100);
    const afterCount = log.querySelectorAll('.terminal-line').length;
    results.push({ cmd, linesAdded: afterCount - beforeCount });
  }
  return results;
}

