async (page) => {
  return await page.evaluate(() => {
    // Find TerminalApp instance if available or trigger via DOM/modules
    // Wait, TerminalApp is imported in TerminalModule.js. Let's check how to access it or trigger via input.
    const input = document.getElementById('terminal-input');
    const log = document.querySelector('.terminal-log');

    if (!document.querySelector('.terminal-panel.is-open')) {
      document.querySelector('.terminal-toggle').click();
    }

    const cmds = [
      'help',
      'help ls',
      'pwd',
      'ls',
      'ls -la',
      'tree',
      'cd experience',
      'pwd',
      'cd ~',
      'pwd',
      'cat about/about.txt',
      'grep victor',
      'man ls',
      'theme dracula',
      'theme claude',
      'lang en',
      'lang es',
      'sound off',
      'sound on',
      'matrix',
      'exit'
    ];

    const results = {};
    for (const cmd of cmds) {
      const before = log.children.length;
      input.value = cmd;
      input.dispatchEvent(new Event('input', { bubbles: true }));
      input.form.dispatchEvent(new Event('submit', { cancelable: true, bubbles: true }));
      const after = log.children.length;
      results[cmd] = Array.from(log.children).slice(before).map(e => e.textContent);
    }
    return results;
  });
}

